import React, { useState } from 'react'
import { View, Text, TouchableOpacity, Dimensions, FlatList } from 'react-native'

import { useContexState } from '../../hooks/context';
import { styles } from './styles';

import api from '../../services/api';

export function ShoppingCart() {
    const { shoppingCartItem, setShoppingCartItem, paymentValue, setPaymentValue, shoppingCartActive, setShoppingCartActive } = useContexState();
    const [startLoad, setStartLoad] = useState(false)


    const numberValue = [122, 3785, 9873, 3122, 45]


    return (!shoppingCartActive ? <>
        <TouchableOpacity onPress={() => {
            setShoppingCartActive(false)
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            //    backgroundColor: '#fff',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />



        <View style={styles.container} >

            <FlatList
                data={numberValue}
                numColumns={3}
                renderItem={({ item }) => <Text style={[styles.listText]}>
                    {(`0000${item}`).slice(-4)}
                </Text>}
            />
        </View>



    </> : null
    );
};

